3	import { useEffect, useState } from "react";
4	import { CONSENT_EVENT, getCookieConsent } from "@/lib/consent";
5	import type { PublicTrackingConfig } from "@/lib/tracking";
6	import { ConversionTags } from "./ConversionTags";
