8	/**
9	 * Consent gate for the ad-tracking pixels. Meta Pixel + Google Ads/GA4 are
10	 * marketing/advertising cookies, so they must not load until the visitor has clicked
11	 * "Accept all" in the cookie banner (`CookieConsent.tsx`, cookie value "all").
12	 *
13	 * SSR renders nothing (consent is unknown on the server); once mounted we read the
14	 * choice and re-measure on the `CONSENT_EVENT` the banner dispatches, so the tags
15	 * come to life the instant a visitor accepts — no page reload required. If the
16	 * operator has set no ids, `ConversionTags` itself still renders nothing, so this
17	 * stays doubly inert until BOTH an id exists AND consent is granted.
18	 */
19	export function ConsentedTags({ config }: { config: PublicTrackingConfig }) {
20	  const [consented, setConsented] = useState(false);
21	
22	  useEffect(() => {
23	    const sync = () => setConsented(getCookieConsent() === "all");
24	    sync();
25	    window.addEventListener(CONSENT_EVENT, sync);
26	    return () => window.removeEventListener(CONSENT_EVENT, sync);
27	  }, []);
28	
29	  if (!consented) return null;
30	  return <ConversionTags config={config} />;
31	}
