1	"use client";
2	
3	import { useEffect } from "react";
4	
5	/**
6	 * Fires the browser-side Purchase conversion when a paid order lands here.
7	 *
8	 * `lib/fulfil-checkout.ts` tags the post-checkout redirect with the real charged
9	 * amount when (and only when) IT performed the fulfilment — `?purchase=1&pv=<value>
10	 * &pc=<currency>&pe=<eventId>`. That same call already fired the server-side Meta
11	 * Conversions API event with the SAME `eventId`, so when the pixel fires here Meta
12	 * dedupes the two into ONE conversion.
13	 *
14	 * We strip the markers from the URL immediately (history.replaceState) so a refresh
15	 * or back-navigation can never double-count, then hand the value to `window.nxTrack`
16	 * (installed by ConversionTags). `nxTrack` only exists once the pixel has loaded,
17	 * which only happens after cookie consent — so with no ids or no consent this is a
18	 * silent no-op, and the CAPI event already covered the conversion server-side.
19	 */
20	export function PurchaseTracker() {
21	  useEffect(() => {
22	    const params = new URLSearchParams(window.location.search);
23	    if (params.get("purchase") !== "1") return;
24	
25	    const value = Number(params.get("pv") ?? "0");
26	    const currency = params.get("pc") ?? "USD";
27	    const eventId = params.get("pe") ?? undefined;
28	
29	    // Strip the markers before doing anything else so a reload/back cannot re-fire.
30	    for (const k of ["purchase", "pv", "pc", "pe"]) params.delete(k);
31	    const qs = params.toString();
32	    window.history.replaceState(
33	      null,
34	      "",
35	      window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash,
36	    );
37	
38	    if (!(value > 0)) return;
39	
40	    // The pixel loads afterInteractive and only once consent is granted — retry a
41	    // few seconds for nxTrack to appear, then give up (CAPI already covered it).
42	    let tries = 0;
43	    let timer: ReturnType<typeof setTimeout> | undefined;
44	    const fire = () => {
45	      const nx = (window as unknown as { nxTrack?: (e: string, p: unknown) => void }).nxTrack;
46	      if (typeof nx === "function") {
47	        nx("Purchase", { value, currency, eventId });
48	        return;
49	      }
50	      if (tries++ < 40) timer = setTimeout(fire, 250);
51	    };
52	    fire();
53	    return () => {
54	      if (timer) clearTimeout(timer);
55	    };
56	  }, []);
57	
58	  return null;
59	}
