6	/**
7	 * True while the cookie banner is on screen waiting for an answer.
8	 *
9	 * The floating chat and feedback controls use this to step out of the banner's
10	 * way. Starts `false` on both server and first client render so hydration
11	 * matches and nothing jumps for the (vast) majority of visitors who have already
12	 * chosen; the effect corrects it within a tick for those who have not.
13	 */
14	export function useConsentPending(): boolean {
15	  const [pending, setPending] = useState(false);
16	
17	  useEffect(() => {
18	    const sync = () => setPending(!hasCookieConsent());
19	    sync();
20	    window.addEventListener(CONSENT_EVENT, sync);
21	    return () => window.removeEventListener(CONSENT_EVENT, sync);
22	  }, []);
23	
24	  return pending;
